import { useNavigate } from "react-router-dom";
import { api } from "../../services/api";
import { Button, Paper, Stack, Typography } from "@mui/material";
import "./Login.css";
import { Form, Formik } from "formik";
import TextField from "../../ui-components/FormsUI/TextField";
import SubmitButton from "../../ui-components/FormsUI/Button";
import { openSnackBar } from "../../ui-components/CustomSnackBar";

const Login = () => {
  const navigate = useNavigate(); // Hook to navigate programmatically

  const validate = (values) => {
    const errors = {};
    if (!values.email) errors.email = "Email is required";
    if (!values.password) errors.password = "Password is required";
    return errors;
  };

  return (
    <div className="login-container">
      <Paper elevation={2} sx={{ p: 3, maxWidth: 520, mx: "auto" }}>
        <Typography variant="h5" component="h2" gutterBottom>
          Login
        </Typography>

        <Formik
          initialValues={{ email: "", password: "" }}
          validate={validate}
          onSubmit={async (values, actions) => {
            actions.setSubmitting(true);
            try {
              const response = await api.post(`/auth/login`, {
                email: values.email,
                password: values.password,
              });

              const { token, role } = response.data;
              localStorage.setItem("token", token); // Store token in localStorage
              localStorage.setItem("role", role); // Store role in localStorage

              if (role === "admin") {
                navigate("/dashboard"); // Navigate to dashboard for admin
              } else {
                navigate("/"); // Navigate to home (Hero)
              }
            } catch (err) {
              console.error("Login failed", err);
              openSnackBar(
                err?.response?.data?.error || "Failed to log in",
                "error"
              );
            } finally {
              actions.setSubmitting(false);
            }
          }}
        >
          {({ isSubmitting }) => (
            <Form noValidate>
              <TextField
                name="email"
                label="Email"
                type="email"
                required
                autoComplete="email"
                placeholder="Enter your email"
              />

              <TextField
                name="password"
                label="Password"
                type="password"
                required
                autoComplete="current-password"
                placeholder="Enter your password"
              />

              <Stack
                direction={{ xs: "column", sm: "row" }}
                spacing={2}
                sx={{ mt: 2 }}
              >
                <SubmitButton
                  variant="contained"
                  fullWidth
                  disabled={isSubmitting}
                >
                  Login
                </SubmitButton>
                <Button
                  type="button"
                  variant="outlined"
                  fullWidth
                  onClick={() => navigate("/signup")}
                >
                  Sign Up
                </Button>
              </Stack>
            </Form>
          )}
        </Formik>
      </Paper>
    </div>
  );
};

export default Login;
