import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import Calories from "../assets/calories.png";
import hero_image from "../assets/hero_image.png";
import hero_image_back from "../assets/hero_image_back.png";
import heart from "../assets/hrt.png";
import Header from "./Header/Header";
import "./Hero.css";
import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Paper,
  Stack,
  Tab,
  Tabs,
  Typography,
} from "@mui/material";

import { api } from "../services/api";

import { motion } from "framer-motion";

const Hero = () => {
  const navigate = useNavigate();
  const transition = { type: "spring", duration: 1.8 };

  const isLoggedIn = Boolean(localStorage.getItem("token"));

  const [tabValue, setTabValue] = useState(0);
  const [dietPlan, setDietPlan] = useState(null);
  const [workoutPlan, setWorkoutPlan] = useState(null);
  const [dietError, setDietError] = useState(null);
  const [workoutError, setWorkoutError] = useState(null);
  const [loadingPlans, setLoadingPlans] = useState(false);

  useEffect(() => {
    if (!isLoggedIn) return;

    let mounted = true;
    setLoadingPlans(true);
    setDietError(null);
    setWorkoutError(null);

    const dietReq = api
      .get("/diet-plan/me")
      .then((res) => {
        if (!mounted) return;
        setDietPlan(res.data);
      })
      .catch((err) => {
        if (!mounted) return;
        if (err?.response?.status === 404) {
          setDietPlan(null);
          return;
        }
        setDietError(err?.response?.data?.error || err.message);
      });

    const workoutReq = api
      .get("/workout-plan/me")
      .then((res) => {
        if (!mounted) return;
        setWorkoutPlan(res.data);
      })
      .catch((err) => {
        if (!mounted) return;
        if (err?.response?.status === 404) {
          setWorkoutPlan(null);
          return;
        }
        setWorkoutError(err?.response?.data?.error || err.message);
      });

    Promise.allSettled([dietReq, workoutReq]).finally(() => {
      if (!mounted) return;
      setLoadingPlans(false);
    });

    return () => {
      mounted = false;
    };
  }, [isLoggedIn]);

  const handleTopRightClick = () => {
    if (isLoggedIn) {
      localStorage.removeItem("token");
      localStorage.removeItem("role");
      navigate("/");
      return;
    }
    navigate("/signup");
  };
  return (
    <div className="hero">
      <div className="blur hero-blur"></div>
      <div className="left-h">
        <Header />

        {/* The best ad*/}
        <div className="the-best-ad">
          <motion.div
            initial={{ left: "262px" }}
            whileInView={{ left: " 6px" }}
            transition={{ ...transition, type: "tween" }}
          ></motion.div>
          <span>The best fitness Club in the town</span>
        </div>

        {/* Hero Heading*/}
        <div className="hero-text">
          <div>
            <span className="stroke-text">Shape</span>
            <span> Your</span>
          </div>
          <div>
            <span>Ideal Body</span>
          </div>
          <div>
            <span>
              In here we will help you to shape and build your ideal body
              andlive up your life to fullest
            </span>
          </div>
        </div>

        {/*figures*/}
        <div className="figures">
          <div>
            <span>+140</span>
            <span>expert coache</span>
          </div>
          <div>
            <span>+978</span>
            <span>members joined</span>
          </div>
          <div>
            <span>+50</span>
            <span>fitness programs</span>
          </div>
        </div>

        {/*hero button*/}
        <div className="hero-button">
          <button className="btn">Get Started</button>
          <button className="btn">Learn More</button>
        </div>

        {isLoggedIn && (
          <Paper elevation={2} sx={{ mt: 3, p: 2, backgroundColor: "transparent" }}>
            <Typography variant="h6" sx={{ color: "white", mb: 1 }}>
              My Assigned Plans
            </Typography>

            <Tabs
              value={tabValue}
              onChange={(_, v) => setTabValue(v)}
              textColor="inherit"
              indicatorColor="primary"
              variant="scrollable"
              allowScrollButtonsMobile
              sx={{ mb: 2 }}
            >
              <Tab label="Diet Plan" />
              <Tab label="Workout Plan" />
            </Tabs>

            {loadingPlans && (
              <Stack direction="row" spacing={1} alignItems="center">
                <CircularProgress size={18} />
                <Typography sx={{ color: "white" }}>Loading plans...</Typography>
              </Stack>
            )}

            {!loadingPlans && tabValue === 0 && (
              <Box>
                {dietError && <Alert severity="error">{dietError}</Alert>}

                {!dietError && !dietPlan && (
                  <Stack spacing={1}>
                    <Typography sx={{ color: "white" }}>
                      No diet plan assigned yet.
                    </Typography>
                    <Button component={Link} to="/registration" variant="contained" size="small">
                      Submit Details
                    </Button>
                    <Button component={Link} to="/diet" variant="outlined" size="small">
                      Open Diet Plan Page
                    </Button>
                  </Stack>
                )}

                {dietPlan && (
                  <Stack spacing={1.5}>
                    <Typography sx={{ color: "white" }}>
                      <b>Status:</b> {dietPlan.status}
                    </Typography>
                    {dietPlan.dailyCalories != null && (
                      <Typography sx={{ color: "white" }}>
                        <b>Daily calories:</b> {dietPlan.dailyCalories}
                      </Typography>
                    )}
                    {dietPlan.generalNotes && (
                      <Typography sx={{ color: "white", whiteSpace: "pre-wrap" }}>
                        <b>Notes:</b> {dietPlan.generalNotes}
                      </Typography>
                    )}

                    <Box>
                      <Typography variant="subtitle1" sx={{ color: "white", mb: 1 }}>
                        Meals
                      </Typography>
                      {dietPlan.meals?.length ? (
                        <Stack spacing={1}>
                          {dietPlan.meals.map((meal, idx) => (
                            <Paper key={idx} variant="outlined" sx={{ p: 1.5 }}>
                              <Typography fontWeight={700}>
                                {meal.mealType || "Meal"}
                                {meal.time ? ` (${meal.time})` : ""}
                              </Typography>
                              {meal.notes ? (
                                <Typography sx={{ whiteSpace: "pre-wrap" }}>{meal.notes}</Typography>
                              ) : null}
                            </Paper>
                          ))}
                        </Stack>
                      ) : (
                        <Typography sx={{ color: "white" }}>No meals listed.</Typography>
                      )}
                    </Box>

                    <Button component={Link} to="/diet" variant="outlined" size="small">
                      View Full Diet Plan
                    </Button>
                  </Stack>
                )}
              </Box>
            )}

            {!loadingPlans && tabValue === 1 && (
              <Box>
                {workoutError && <Alert severity="error">{workoutError}</Alert>}

                {!workoutError && !workoutPlan && (
                  <Stack spacing={1}>
                    <Typography sx={{ color: "white" }}>
                      No workout plan assigned yet.
                    </Typography>
                    <Button component={Link} to="/registration" variant="contained" size="small">
                      Submit Details
                    </Button>
                    <Button component={Link} to="/workout" variant="outlined" size="small">
                      Open Workout Plan Page
                    </Button>
                  </Stack>
                )}

                {workoutPlan && (
                  <Stack spacing={1.5}>
                    <Typography sx={{ color: "white" }}>
                      <b>Status:</b> {workoutPlan.status}
                    </Typography>
                    {workoutPlan.planName && (
                      <Typography sx={{ color: "white" }}>
                        <b>Plan:</b> {workoutPlan.planName}
                      </Typography>
                    )}
                    {workoutPlan.scheduleType && (
                      <Typography sx={{ color: "white" }}>
                        <b>Schedule type:</b> {workoutPlan.scheduleType}
                      </Typography>
                    )}
                    {workoutPlan.generalInstructions && (
                      <Typography sx={{ color: "white", whiteSpace: "pre-wrap" }}>
                        <b>Instructions:</b> {workoutPlan.generalInstructions}
                      </Typography>
                    )}

                    <Box>
                      <Typography variant="subtitle1" sx={{ color: "white", mb: 1 }}>
                        Workout Days
                      </Typography>
                      {workoutPlan.workoutDays?.length ? (
                        <Stack spacing={1}>
                          {workoutPlan.workoutDays.map((day, idx) => (
                            <Paper key={idx} variant="outlined" sx={{ p: 1.5 }}>
                              <Typography fontWeight={700}>
                                Day {day.dayNumber}
                                {day.dayName ? ` - ${day.dayName}` : ""}
                              </Typography>
                              {day.exercises?.length ? (
                                <Box component="ul" sx={{ m: 0, pl: 2 }}>
                                  {day.exercises.map((ex, exIdx) => (
                                    <li key={exIdx}>
                                      {ex.name}
                                      {ex.sets != null ? ` | sets: ${ex.sets}` : ""}
                                      {ex.reps ? ` | reps: ${ex.reps}` : ""}
                                    </li>
                                  ))}
                                </Box>
                              ) : (
                                <Typography>No exercises listed.</Typography>
                              )}
                            </Paper>
                          ))}
                        </Stack>
                      ) : (
                        <Typography sx={{ color: "white" }}>No workout days listed.</Typography>
                      )}
                    </Box>

                    <Button component={Link} to="/workout" variant="outlined" size="small">
                      View Full Workout Plan
                    </Button>
                  </Stack>
                )}
              </Box>
            )}
          </Paper>
        )}
      </div>

      <div className="right-h">
        <button className="btn" onClick={handleTopRightClick}>
          {isLoggedIn ? "Logout" : "Join Now"}
        </button>

        {/* heart-rate  */}
        <motion.div
          initial={{ right: "-1rem" }}
          whileInView={{ right: "4rem" }}
          transition={transition}
          className="heart-rate"
        >
          <img src={heart} alt="Heart" />
          <span>Heart Rate</span>
          <span>116 bpm</span>
        </motion.div>

        {/* hero images */}
        <img src={hero_image} alt="" className="hero-image" />

        {/* hero-back image  */}
        <motion.img
          initial={{ right: "20rem" }}
          whileInView={{ right: "30rem" }}
          transition={transition}
          src={hero_image_back}
          alt=""
          className="hero-image-back"
        />

        {/* calories */}
        <motion.div
          initial={{ right: "39rem" }}
          whileInView={{ right: "32rem" }}
          transition={transition}
          className="calories"
        >
          <img src={Calories} alt="" />
          <div>
            <span>Calories Burned</span>
            <span>220 kcal</span>
          </div>
        </motion.div>
      </div>
    </div>
  );
};

export default Hero;
