import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { useGlobalContext } from "../../contexts/GlobalContext";
import { Button, Stack, TextField } from "@mui/material";
import "./adminDashTable.css";

export const AdminDashTable = ({ view = "approved" }) => {
  const { getAll, getRejected, updateStatus, users } = useGlobalContext();

  const [adminNotes, setAdminNotes] = useState("");

  useEffect(() => {
    if (view === "rejected") {
      getRejected();
    } else {
      getAll();
    }
  }, [view, getAll, getRejected]);

  const onSetStatus = async (id, status) => {
    await updateStatus(id, status, adminNotes);
    await getAll();
  };

  return (
    <div className="admin-dash-table-container">
      <Button
        variant="outlined"
        onClick={() => (view === "rejected" ? getRejected() : getAll())}
      >
        Refresh
      </Button>
      <div className="container mt-5">
        {users && (
          <table className="schedule-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Schedule Type</th>
                <th>Age</th>
                <th>Gender</th>
                <th>Weight(KG)</th>
                <th>Payment Slip</th>
                <th>Status</th>
                <th>Option</th>
              </tr>
            </thead>
            <tbody>
              {users.map((user, index) => (
                <tr key={index}>
                  <td>{user.name}</td>
                  <td>{user.scheduleType}</td>
                  <td>{user.age}</td>
                  <td>{user.gender}</td>
                  <td>{user.weight}</td>
                  <td>{user.paymentSlip.name}</td>
                  <td>{user.status}</td>
                  <td>
                    <Button
                      component={Link}
                      to={`/createworkout/${user._id}`}
                      variant="contained"
                      size="small"
                    >
                      Assign plans
                    </Button>

                    <div style={{ marginTop: "0.5rem" }}>
                      <TextField
                        placeholder="Admin notes (optional)"
                        value={adminNotes}
                        onChange={(e) => setAdminNotes(e.target.value)}
                        size="small"
                        fullWidth
                      />
                    </div>

                    <div
                      style={{
                        marginTop: "0.5rem",
                        display: "flex",
                        gap: "0.5rem",
                        flexWrap: "wrap",
                      }}
                    >
                      {view === "rejected" ? (
                        <Stack direction="row" spacing={1} flexWrap="wrap">
                          <Button
                            variant="outlined"
                            size="small"
                            onClick={() => onSetStatus(user._id, "approved")}
                          >
                            Move to approved
                          </Button>
                        </Stack>
                      ) : (
                        <Stack direction="row" spacing={1} flexWrap="wrap">
                          <Button
                            variant="outlined"
                            size="small"
                            onClick={() => onSetStatus(user._id, "rejected")}
                          >
                            Reject
                          </Button>
                        </Stack>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};
