import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { api } from "../../services/api";
import {
  Button,
  Paper,
  Stack,
  Typography,
} from "@mui/material";
import "./RegistrationForm.css";
import { Form, Formik } from "formik";
import TextField from "../../ui-components/FormsUI/TextField";
import Select from "../../ui-components/FormsUI/Select";
import SubmitButton from "../../ui-components/FormsUI/Button";
import { openSnackBar } from "../../ui-components/CustomSnackBar";

const RegistrationForm = () => {
  const [paymentSlip, setPaymentSlip] = useState(null);
  const [frontBodyPicture, setFrontBodyPicture] = useState(null);
  const [backBodyPicture, setBackBodyPicture] = useState(null);

  const navigate = useNavigate();

  const validate = (values) => {
    const errors = {};
    if (!values.scheduleType) errors.scheduleType = "Schedule type is required";
    if (!values.name) errors.name = "Name is required";
    if (!values.age) errors.age = "Age is required";
    if (!values.gender) errors.gender = "Gender is required";
    if (!values.weight) errors.weight = "Weight is required";
    if (!values.whatsappNumber) errors.whatsappNumber = "WhatsApp number is required";
    return errors;
  };

  const scheduleTypeOptions = [
    { value: "Body Building", label: "Body Building" },
    { value: "Fat Burning", label: "Fat Burning" },
    { value: "Ladies", label: "Ladies" },
  ];

  const genderOptions = [
    { value: "Male", label: "Male" },
    { value: "Female", label: "Female" },
  ];

  return (
    <div className="registration-form-container">
      <Paper elevation={2} sx={{ p: 3, maxWidth: 720, mx: "auto" }}>
        <Typography variant="h5" component="h2" gutterBottom>
          Workout and Diet Plan Request Form
        </Typography>

        <Formik
          initialValues={{
            scheduleType: "",
            name: "",
            age: "",
            gender: "",
            weight: "",
            whatsappNumber: "",
          }}
          validate={validate}
          onSubmit={async (values, actions) => {
            actions.setSubmitting(true);

            if (!paymentSlip || !frontBodyPicture || !backBodyPicture) {
              openSnackBar("Please upload all required files", "error");
              actions.setSubmitting(false);
              return;
            }

            const formData = new FormData();
            formData.append("scheduleType", values.scheduleType);
            formData.append("name", values.name);
            formData.append("age", values.age);
            formData.append("gender", values.gender);
            formData.append("weight", values.weight);
            formData.append("whatsappNumber", values.whatsappNumber);
            formData.append("paymentSlip", paymentSlip);
            formData.append("frontBodyPicture", frontBodyPicture);
            formData.append("backBodyPicture", backBodyPicture);

            try {
              const res = await api.post("/register/add", formData, {
                headers: {
                  "Content-Type": "multipart/form-data",
                },
              });
              console.log(res.data);
              openSnackBar("Registration submitted successfully!", "success");
              navigate("/");
            } catch (err) {
              console.error(err);
              openSnackBar(
                err?.response?.data?.error || "Registration failed",
                "error"
              );
            } finally {
              actions.setSubmitting(false);
            }
          }}
        >
          {({ isSubmitting }) => (
            <Form noValidate>
              <Stack spacing={2}>
                <Select
                  name="scheduleType"
                  label="Schedule Type"
                  options={scheduleTypeOptions}
                  customHandleChange={() => {}}
                  required
                />

                <TextField
                  name="name"
                  label="Name"
                  required
                  autoComplete="name"
                  placeholder="Enter your full name"
                />

                <TextField
                  name="age"
                  label="Age"
                  type="number"
                  required
                  placeholder="Enter your age"
                  inputProps={{ min: 0 }}
                />

                <Select
                  name="gender"
                  label="Gender"
                  options={genderOptions}
                  customHandleChange={() => {}}
                  required
                />

                <TextField
                  name="weight"
                  label="Weight (kg)"
                  type="number"
                  required
                  placeholder="Enter your weight"
                  inputProps={{ min: 0 }}
                />

                <TextField
                  name="whatsappNumber"
                  label="WhatsApp Number"
                  required
                  autoComplete="tel"
                  placeholder="Enter your WhatsApp number"
                />

                <Stack spacing={1.5}>
                  <Typography variant="subtitle1">Uploads</Typography>

                  <Stack
                    direction={{ xs: "column", sm: "row" }}
                    spacing={2}
                    alignItems={{ sm: "center" }}
                  >
                    <Button variant="outlined" component="label">
                      Payment Slip *
                      <input
                        type="file"
                        hidden
                        accept="image/*"
                        onChange={(e) => setPaymentSlip(e.target.files[0])}
                      />
                    </Button>
                    <Typography variant="body2">
                      {paymentSlip?.name || "No file selected"}
                    </Typography>
                  </Stack>

                  <Stack
                    direction={{ xs: "column", sm: "row" }}
                    spacing={2}
                    alignItems={{ sm: "center" }}
                  >
                    <Button variant="outlined" component="label">
                      Front Body Picture *
                      <input
                        type="file"
                        hidden
                        accept="image/*"
                        onChange={(e) => setFrontBodyPicture(e.target.files[0])}
                      />
                    </Button>
                    <Typography variant="body2">
                      {frontBodyPicture?.name || "No file selected"}
                    </Typography>
                  </Stack>

                  <Stack
                    direction={{ xs: "column", sm: "row" }}
                    spacing={2}
                    alignItems={{ sm: "center" }}
                  >
                    <Button variant="outlined" component="label">
                      Back Body Picture *
                      <input
                        type="file"
                        hidden
                        accept="image/*"
                        onChange={(e) => setBackBodyPicture(e.target.files[0])}
                      />
                    </Button>
                    <Typography variant="body2">
                      {backBodyPicture?.name || "No file selected"}
                    </Typography>
                  </Stack>
                </Stack>

                <SubmitButton
                  variant="contained"
                  size="large"
                  disabled={isSubmitting}
                >
                  {isSubmitting ? "Submitting..." : "Submit"}
                </SubmitButton>
              </Stack>
            </Form>
          )}
        </Formik>
      </Paper>
    </div>
  );
};

export default RegistrationForm;
