import React from "react";
import "./Signup.css";
import { Link as RouterLink, useNavigate } from "react-router-dom";
import { api } from "../../services/api";
import {
  Alert,
  Link,
  Paper,
  Stack,
  Typography,
} from "@mui/material";
import { Form, Formik } from "formik";
import TextField from "../../ui-components/FormsUI/TextField";
import SubmitButton from "../../ui-components/FormsUI/Button";

function SignUp() {
  const navigate = useNavigate();

  const validate = (values) => {
    const errors = {};
    if (!values.email) errors.email = "Email is required";
    if (!values.password) errors.password = "Password is required";
    if (!values.confirmPassword)
      errors.confirmPassword = "Confirm Password is required";
    if (
      values.password &&
      values.confirmPassword &&
      values.password !== values.confirmPassword
    ) {
      errors.confirmPassword = "Passwords do not match";
    }
    return errors;
  };

  return (
    <div className="sign-up-container">
      <Paper elevation={2} sx={{ p: 3, maxWidth: 560, mx: "auto" }}>
        <Typography variant="h5" component="h2" gutterBottom>
          Sign Up
        </Typography>

        <Formik
          initialValues={{ email: "", password: "", confirmPassword: "" }}
          validate={validate}
          onSubmit={async (values, actions) => {
            actions.setSubmitting(true);
            actions.setStatus(undefined);

            try {
              const response = await api.post("/user/signup", {
                email: values.email,
                password: values.password,
                confirmPassword: values.confirmPassword,
              });

              console.log(response.data);
              navigate("/");
            } catch (err) {
              actions.setStatus(err?.response?.data?.error || err.message);
            } finally {
              actions.setSubmitting(false);
            }
          }}
        >
          {({ isSubmitting, status }) => (
            <Form noValidate className="my-form">
              <TextField
                name="email"
                label="Email"
                type="email"
                required
                autoComplete="email"
                placeholder="Enter your email"
              />

              <TextField
                name="password"
                label="Password"
                type="password"
                required
                autoComplete="new-password"
                placeholder="Create a password"
              />

              <TextField
                name="confirmPassword"
                label="Confirm Password"
                type="password"
                required
                autoComplete="new-password"
                placeholder="Re-enter your password"
              />

              {status && (
                <Alert severity="error" sx={{ mt: 1 }}>
                  {status}
                </Alert>
              )}

              <Stack spacing={1.5} sx={{ mt: 2 }}>
                <SubmitButton
                  variant="contained"
                  fullWidth
                  disabled={isSubmitting}
                >
                  Sign Up
                </SubmitButton>

                <Typography variant="body2">
                  Already have an account?{" "}
                  <Link component={RouterLink} to="/login" underline="hover">
                    Login
                  </Link>
                </Typography>
              </Stack>
            </Form>
          )}
        </Formik>
      </Paper>
    </div>
  );
}

export default SignUp;
